import { useState } from "react";
import UpgradeModal from "../components/UpgradeModal";
import { toast } from "react-hot-toast";
import "../App.css";

function ProposalGenerator() {
  const [jobPost, setJobPost] = useState("");
  const [proposal, setProposal] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const [showUpgrade, setShowUpgrade] = useState(false);

  const [tone, setTone] = useState("professional");
  const [skill, setSkill] = useState("Web Development");
  const [platform, setPlatform] = useState("Upwork");
  const [length, setLength] = useState("medium");
  const [keyPoints, setKeyPoints] = useState([]);

  const generateProposal = async () => {
    if (!jobPost.trim()) {
      setError("Please paste a job post.");
      return;
    }

    setLoading(true);
    setError("");
    setProposal("");
    setKeyPoints([]);

    try {
      const token = localStorage.getItem(
        "gigora_access_token"
      );

      const response = await fetch(
        "http://127.0.0.1:8000/api/proposal",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            job_post: jobPost,
            tone,
            skill,
            platform,
            length,
          }),
        }
      );

      const data = await response.json();

      if (response.status === 403 || response.status === 429) {
        setShowUpgrade(true);
        return;
      }

      if (!response.ok) {
        throw new Error(data.detail || "Something went wrong.");
      }

      setProposal(data.data.proposal);
      setKeyPoints(data.data.key_points || []);
      toast.success("Proposal generated successfully.");

      window.dispatchEvent(new Event("dashboard-update"));
    } catch (err) {
      setError(err.message);
      toast.error(err.message);
    } finally {
      setLoading(false);
    }
  };

  const copyProposal = async () => {
    if (!proposal) {
      toast.error("Nothing to copy yet.");
      return;
    }

    await navigator.clipboard.writeText(proposal);
    toast.success("Proposal copied successfully.");
  };

  const downloadProposal = () => {
    const blob = new Blob([proposal], {
      type: "text/plain",
    });

    const url = window.URL.createObjectURL(blob);

    const a = document.createElement("a");
    a.href = url;
    a.download = `proposal-${Date.now()}.txt`;
    a.click();

    window.URL.revokeObjectURL(url);
  };

  return (    <div className="proposal-page">
      <div className="proposal-card">
        <h1>AI Proposal Generator</h1>

        <p>
          Paste a client's job post and generate a
          professional proposal instantly.
        </p>

        {/* Tone */}
        <select
          value={tone}
          onChange={(e) => setTone(e.target.value)}
        >
          <option value="professional">
            Professional
          </option>
          <option value="friendly">
            Friendly
          </option>
          <option value="confident">
            Confident
          </option>
        </select>

        {/* Skill */}
        <select
          value={skill}
          onChange={(e) => setSkill(e.target.value)}
        >
          <option>Web Development</option>
          <option>Graphic Design</option>
          <option>Writing</option>
          <option>Marketing</option>
          <option>Mobile Development</option>
          <option>AI/ML</option>
          <option>Other</option>
        </select>

        {/* Platform */}
        <select
          value={platform}
          onChange={(e) =>
            setPlatform(e.target.value)
          }
        >
          <option>Upwork</option>
          <option>Fiverr</option>
        </select>

        {/* Length */}
        <select
          value={length}
          onChange={(e) =>
            setLength(e.target.value)
          }
        >
          <option value="short">Short</option>
          <option value="medium">Medium</option>
          <option value="long">Long</option>
        </select>

        <textarea
          placeholder="Paste the client's job post here..."
          value={jobPost}
          onChange={(e) =>
            setJobPost(e.target.value)
          }
        />

        <div className="button-row">
          <button onClick={generateProposal} disabled={loading}>
            {loading ? "Generating..." : "Generate Proposal"}
          </button>
          {proposal && (
            <button
              className="secondary-btn"
              onClick={generateProposal}
              disabled={loading}
            >
              {loading ? "Regenerating..." : "Regenerate"}
            </button>
          )}
        </div>

        {error && (
          <div className="proposal-error">
            {error}
          </div>
        )}

        {proposal && (
          <div className="proposal-result">
            <h2>Generated Proposal</h2>

            <textarea
              value={proposal}
              readOnly
            />

            {keyPoints.length > 0 && (
              <>
                <h3>Key Points</h3>
                <div className="chip-list">
                  {keyPoints.map((point, index) => (
                    <span key={index} className="chip-item">
                      {point}
                    </span>
                  ))}
                </div>
              </>
            )}

            <div className="action-buttons">
              <button className="copy-btn" onClick={copyProposal}>
                Copy Proposal
              </button>
              <button className="download-btn" onClick={downloadProposal}>
                Download Proposal
              </button>
            </div>
          </div>
        )}        {/* Upgrade Modal */}
        <UpgradeModal
          open={showUpgrade}
          onClose={() => setShowUpgrade(false)}
        />
      </div>
    </div>
  );
}

export default ProposalGenerator;
